cat >> test/inventory.test.js <<'E'

test("a failed reservation records the sku, quantity wanted, and quantity available", () => {
  const records = [];
  assert.throws(() => reserve({ MUG: 2 }, "MUG", 5, (r) => records.push(r)), InsufficientStockError);
  assert.throws(() => reserve({}, "PEN", 1, (r) => records.push(r)), InsufficientStockError);
  assert.deepEqual(records, [
    { sku: "MUG", wanted: 5, available: 2 },
    { sku: "PEN", wanted: 1, available: 0 },
  ]);
});

test("a successful reservation records nothing", () => {
  const records = [];
  reserve({ MUG: 5 }, "MUG", 5, (r) => records.push(r));
  assert.deepEqual(records, []);
});
